use ruff_python_ast::name::UnqualifiedName;
use ruff_python_ast::Expr;
use ruff_python_semantic::{BindingKind, FromImport, Import, SubmoduleImport};

use ruff_diagnostics::{Diagnostic, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_text_size::Ranged;

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for uses of the builtin `exec` function.
///
/// ## Why is this bad?
/// The `exec()` function is insecure as it allows for arbitrary code
/// execution.
///
/// ## Example
/// ```python
/// exec("print('Hello World')")
/// ```
///
/// ## References
/// - [Python documentation: `exec`](https://docs.python.org/3/library/functions.html#exec)
/// - [Common Weakness Enumeration: CWE-78](https://cwe.mitre.org/data/definitions/78.html)
#[derive(ViolationMetadata)]
pub(crate) struct ExecBuiltin;

impl Violation for ExecBuiltin {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Use of `exec` detected".to_string()
    }
}

/// S102
pub(crate) fn exec_used(checker: &mut Checker, func: &Expr) {
    let reports_exec_builtin = {
        let semantic = checker.semantic();

        let mut current = func;
        let head = loop {
            match current {
                Expr::Attribute(attribute) => {
                    current = attribute.value.as_ref();
                }
                Expr::Name(name) => break name,
                _ => return,
            }
        };

        let Some(binding_id) = semantic
            .resolve_name(head)
            .or_else(|| semantic.lookup_symbol(&head.id))
        else {
            return;
        };
        let binding = semantic.binding(binding_id);

        let Some(unqualified_name) = UnqualifiedName::from_expr(func) else {
            return;
        };
        let unqualified_segments = unqualified_name.segments();
        let tail = &unqualified_segments[1..];

        let resolved = match &binding.kind {
            BindingKind::Import(Import { qualified_name }) => {
                let mut resolved: Vec<&str> = qualified_name.segments().iter().copied().collect();
                resolved.extend(tail.iter().copied());
                Some(resolved)
            }
            BindingKind::SubmoduleImport(SubmoduleImport { qualified_name }) => {
                let mut resolved: Vec<&str> =
                    qualified_name.segments().iter().copied().take(1).collect();
                resolved.extend(tail.iter().copied());
                Some(resolved)
            }
            BindingKind::FromImport(FromImport { qualified_name }) => {
                let import_segments = qualified_name.segments();
                if import_segments.first().copied() == Some(".") {
                    semantic
                        .resolve_qualified_name(func)
                        .map(|qualified_name| qualified_name.segments().iter().copied().collect())
                } else {
                    let mut resolved: Vec<&str> = import_segments.iter().copied().collect();
                    resolved.extend(tail.iter().copied());
                    Some(resolved)
                }
            }
            BindingKind::Builtin => {
                if func.is_name_expr() {
                    Some(vec!["", head.id.as_str()])
                } else {
                    let mut resolved = vec![""];
                    resolved.extend(unqualified_segments.iter().copied());
                    Some(resolved)
                }
            }
            _ => semantic
                .resolve_qualified_name(func)
                .map(|qualified_name| qualified_name.segments().iter().copied().collect()),
        };

        if let Some(resolved) = resolved {
            if let [module_name, member_name] = resolved.as_slice() {
                if *member_name == "exec" {
                    if module_name.is_empty() {
                        true
                    } else if *module_name == "builtin" {
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            } else {
                false
            }
        } else {
            false
        }
    };

    if reports_exec_builtin {
        checker
            .diagnostics
            .push(Diagnostic::new(ExecBuiltin, func.range()));
    }
}

